export default {
	data() {
		return {
			// onPullDownRefresh: function () {
			//   wx.stopPullDownRefresh()
			// },
			userName:"",
			userCode:"",
			userCodeConfirm:"",
			clicked: false
		};
	},

	components: {},
	props: {},
	onLoad: function() {
		console.log(this.$data.userName);
	},
		
	methods:{
		onClickRegi: function() {
			var that=this;
			if (!this.$data.clicked){
				if (this.$data.userCodeConfirm.length<6){
					uni.showToast({
						title:'密码需要至少6位',
						icon:'none',
						position:'bottom'
					})
					console.log("密码需要至少6位");
				}
				else{
					
					if (this.$data.userCodeConfirm.localeCompare(this.$data.userCode)==0){
						console.log("密码符合");
						this.setData({
							clicked:true
						})
						uni.request({
							url: 'https://lej4kht0ig.execute-api.us-east-2.amazonaws.com/CLF/reginewuser',
							method: 'POST',
							data: {
								userName: this.$data.userName,
								userCode: this.$data.userCodeConfirm,
							},
							success: function(res) {
								if (res.data.localeCompare("Nope!")==0){
									//already registered
									uni.showToast({
										title:'用户名已被使用',
										icon:'none',
										position:'bottom'
									})
									console.log("用户名已被使用");
								}else{
									//registered
									uni.showToast({
										title:'注册成功',
										icon:'none',
										position:'bottom'
									})
									console.log("注册成功");
									uni.navigateTo({
										url: '../login/login',
									});
								}
								that.setData({
									clicked:false
								})
							},
						})
					}else{
						console.log("密码不和");
						
					}
				}
			}
		},
		setData: function(obj, callback) {
			let that = this;
			let keys = [];
			let val, data;
			Object.keys(obj).forEach(function(key) {
				keys = key.split('.');
				val = obj[key];
				data = that.$data;
				keys.forEach(function(key2, index) {
					if (index + 1 == keys.length) {
						that.$set(data, key2, val);
					} else {
						if (!data[key2]) {
							that.$set(data, key2, {});
						}
					}
		
					data = data[key2];
				});
			});
			callback && callback();
		}
	}
	
}
